const updateMovie = `-- name: UpdateMovie :exec
UPDATE movies
SET year = $1,
    release_date = $2,
    genre = $3,
    director = $4,
    "cast" = $5,
    content_rating = $6,
    maturity_rating = $7,
    content_advisories = $8,
    plot = $9,
    tagline = $10,
    original_title = $11,
    sort_title = $12,
    imdb_id = $13,
    tmdb_id = $14,
    runtime_minutes = $15,
    budget = $16,
    revenue = $17,
    original_language = $18,
    country_of_origin = $19,
    awards_summary = $20
WHERE media_id = $21
`

